-- 운영 DB 확인용 읽기 전용 점검. 자동 실행하지 않는다.
-- 권한이 제한된 읽기 전용 계정으로 실행하고, 결과는 개인정보를 포함하지 않게 보관한다.
-- 산·코스 차이 목록과 참조 오류 건수는 모두 0이어야 기준 seed와 일치한다.
-- path는 seed에 저장된 문자열의 MD5를 비교한다. 공백만 달라도 차이로 보고한다.
BEGIN TRANSACTION READ ONLY;
SELECT current_database() AS database_name, current_timestamp AS checked_at;
WITH expected (id, name, region, sigungu_code, sigungu_name, address, height, lat, lng, grid_nx, grid_ny, description) AS (VALUES
(1, '가덕산', 'EAST', '41820', '가평군', '경기도 가평군 북면 목동리', 857.5, 37.940394, 127.612586, 71, 135, '경기 제1봉인 화악산(1,468m)에서 동남쪽으로 뻗어 내린 능선 상에 솟아 있는 가덕산은 몽덕산과 북배산의 능선 중간에 자리 잡고 있다. 억새산이라고 할 만큼 가을철에 억새가 볼만하다.'),
(2, '계관산', 'EAST', '41820', '가평군', '경기도 가평군 가편읍 개곡리', 730.0, 37.889733, 127.60784, 70, 134, '몽덕산(680m)에서 뻗어 내린 능선이 가덕산(858m), 북배산(867m)을 일으키고 싸리재를 지나 서남쪽으로 이어지는 능선에 우뚝 솟아 있는 계관산은 강원도 춘천시 서면과 경기도 가평군 북면의 경계를 이루는 산이다.'),
(3, '고동산', 'EAST', '41820', '가평군', '경기도 가평군 청평면 삼회리', 591.0, 37.655699, 127.401476, 67, 129, '가평의 청평호 건너편에 화야산, 뽀루봉과 함께 한 능선으로 연결된 산이다. 잔솔과 참나무가 많고 낙엽이 수북한 능선길은 사람의 마음을 편하게 해주며 울창한 수림과 깊은 계곡은 마치 높은 산을 오르는 듯한 감동을 준다.'),
(4, '노적봉', 'EAST', '41820', '가평군', '경기도 가평군 가편읍 마장리', 859.0, 37.8818039, 127.4793422, 68, 134, '구나무산 서남쪽 산자락에는 일명 물안골로 불리는 용추계곡이 자리 잡고 있으며 이 계곡에는 용추폭포, 미륵바위, 소바위, 곰바위 등 볼거리가 널려 있다. 이름 그대로 구나무가 많아 구나무산이라 불린다.'),
(5, '명지산', 'EAST', '41820', '가평군', '경기도 가평군 북면 도대리', 1252.3, 37.941272, 127.432468, 67, 135, '경기도에서 화악산(1468)에 이어 두 번째로 높은 명지산은 정상을 오를 수 있는 산으로는 최고봉이다. 거대한 산맥을 이룬 명지산은 산 크기만큼이나 등산로도 많이 있으나 어느 길이나 정상까지 3시간 이상 소요된다.'),
(6, '민둥산 (경기)', 'EAST', '41820', '가평군', '경기도 가평군 북면 적목리', 1010.0, 37.99016, 127.40544, 67, 136, '민둥산은 1,023m의 제법 높은 산으로 주변에는 국망봉, 강씨봉, 청계산, 귀목봉 등 산세가 아름다운 산들이 모여있다. 민둥산은 민드기봉, 민덕산이라고도 하며 적목리 서쪽 한북정맥에 솟아있는 산이다.'),
(7, '백둔봉', 'EAST', '41820', '가평군', '경기도 가평군 북면 도대리', 970.0, 37.9240283, 127.4511024, 68, 135, '가평군 북면 도대리에 있는 해발 970m의 산이다. 명지산과 연인산 사이 능선에 있다.'),
(8, '북배산', 'EAST', '41820', '가평군', '경기도 가평군 북면 목동리', 869.6, 37.920425, 127.612659, 71, 135, '북배산은 고향 집 바로 뒤에 솟아 있는 산처럼 향수를 자아내게 하는 산으로 크게 빼어나지도 웅장하지도 않지만 수수한 매무새의 시골 아낙 같은 자태를 보인다. 가덕산(858m)과 계관산(710m)으로 이어지는 능선에 위치하며 청정지역에 있는 산답게 깨끗하고 고즈넉한 산이다.'),
(9, '석룡산', 'EAST', '41820', '가평군', '경기도 가평군 북면 적목리', 1147.4, 38.0062272, 127.4763094, 68, 136, '가평군 북면 적목리에 있는 해발 1147.4m의 산이다. 화악산 북서쪽에 있으며 조무락골 계곡을 끼고 있다.'),
(10, '연인산', 'EAST', '41820', '가평군', '경기도 가평군 조종면 상판리', 1076.8, 37.898779, 127.414435, 67, 134, '연인산은 경기도 제2의 고봉 명지산의 남녘 능선을 잇는 산이다. 가평군 제1의 휴양지인 용추계곡 최상류에 자리하고 있다.'),
(11, '장락산', 'EAST', '41820', '가평군', '경기도 가평군 설악면 위곡리', 629.5, 37.680549, 127.549818, 70, 129, '용문산 북쪽의 992m 봉에서 북으로 분기하여 늪산(봉미산)을 빚고 홍천강으로 빠져들기 직전에 장락산을 만들었다. 능선 주변에는 기암이 곳곳에 있고 노송이 어우러져 아름다운 데다 굽이굽이 흐르는 홍천강을 시종 바라보면서 걸을 수 있는 능선길이 더욱 운치 있다.'),
(12, '축령산 (경기)', 'EAST', '41820', '가평군', '경기도 가평군 상면 행현리', 887.1, 37.752763, 127.333886, 66, 131, '화도읍(마석)에서 북동쪽으로 12km 거리에 있는 축령산(879m)은 조종천과 수동천의 사이에 솟아 있다. 이 산에는 일명 ''남이바위''라고 하는 바위가 있는데, 이는 조선 시대 때 남이 장군이 이곳에서 심신을 수련하였다 하여 붙여진 이름이라고 한다.'),
(13, '칼봉산', 'EAST', '41820', '가평군', '경기도 가평군 가평읍 경반리', 909.5, 37.862906, 127.436602, 68, 133, '경기도 가평군 가평읍 승안리와 경반리의 경계를 이루는 칼봉산은 수락폭포와 용추폭포로 유명한 산이다. 가평읍에서 경반리 골짜기 안으로 12km 거리에 있는 수락폭포는 높이 30m쯤 되는 비교적 큰 폭포이다.'),
(14, '화악산 (경기/강원)', 'EAST', '41820', '가평군', '경기도 가평군 북면 화악리', 1468.3, 37.989373, 127.498228, 69, 136, '예부터 화악산은 지리적으로 한반도의 정중앙으로 알려져 왔다. 우리나라 지도를 볼 때 전남 여수에서 북한 중강진으로 일직선으로 이어지는 선이 국토 자오선(동경 127도 30분)이다.'),
(15, '화야산', 'EAST', '41820', '가평군', '경기도 가평군 설악면 이천리', 754.2, 37.671577, 127.427916, 67, 129, '높이 755m의 화야산은 북한강이 북에서 서쪽으로 감싸고 흘러내리는 가운데에 있다. 산 위에서의 전망이 좋고 강물을 내려다보며 산을 오르는 이색적인 기분을 맛볼 수 있다.'),
(16, '앵봉산 (서울/경기)', 'NORTH', '41280', '고양시', '경기도 고양시 덕양구 서오릉로', 235.0, 37.6297001, 126.9082513, 59, 128, '고양시 덕양구 서오릉로에 있는 해발 235m의 산이다. 서울 은평구와 고양시 경계에 있으며 서오릉을 품고 있다.'),
(17, '우면산', 'CENTRAL', '41290', '과천시', '경기도 과천시 과천동', 312.6, 37.47048, 127.00913, 60, 125, '과천시 과천동에 있는 해발 312.6m의 산이다. 서울 서초구와 과천시 경계에 있으며 북쪽 기슭에 예술의전당이 있다.'),
(18, '청계산 (경기/서울)', 'CENTRAL', '41290', '과천시', '경기도 과천시 막계동 / 서울특별시 서초구 원지동', 616.3, 37.421899, 127.0432171, 61, 124, '과천, 성남, 의왕의 등산로가 있어 등산하기에 좋은 산이며 이수봉, 국사봉에서 내려다보는 경관이 매우 아름답다.'),
(19, '구름산', 'CENTRAL', '41210', '광명시', '경기도 광명시 하안동', 240.8, 37.440565, 126.866238, 58, 124, '광명시 하안동에 있는 해발 240.8m의 산이다.'),
(20, '검단산 (성남/광주)', 'EAST', '41610', '광주시', '경기도 광주시 남한산성면 검복리', 536.4, 37.45805, 127.187529, 63, 124, '광주시 남한산성면 검복리에 있는 해발 536.4m의 산이다. 남한산성 남쪽으로 이어지는 능선에 있으며 성남시와 광주시의 경계를 이룬다.'),
(21, '국사봉 (경기)', 'EAST', '41610', '광주시', '경기도 광주시 남종면 금사리', 207.3, 37.479589, 127.311731, 66, 125, '국사봉은 퇴촌면 도수리와 남종면 금사리에 있으나, 국사봉 등산로의 대부분은 퇴촌면 도수리 쪽에 편입되어 있으며, 등산로는 동서로 길게 늘어졌고 능선의 동쪽으로는 해협산(海峽山)이 자리 잡고 있다.'),
(22, '대지산 (경기)', 'EAST', '41610', '광주시', '경기도 광주시 오포읍 능평리', 326.0, 37.33632, 127.14195, 63, 122, '광주시 오포읍 능평리에 있는 해발 326m의 산이다.'),
(23, '문형산', 'EAST', '41610', '광주시', '경기도 광주시 오포읍 신현리', 496.7, 37.370453, 127.191007, 64, 123, '산 이름에서부터 대단한 품위가 느껴지는 산이다. 문형(文衡)이란 고려나 조선 때에 대제학(大提學)의 별칭으로, 학자들에게 가장 품격 높은 벼슬이다.'),
(24, '불곡산 (성남/광주)', 'EAST', '41610', '광주시', '경기도 광주시 오포읍 신현리', 335.4, 37.351691, 127.134448, 63, 122, '경기도 성남시 분당구 정자동과 광주시 오포읍의 경계에 있는 산으로 자연 생태계가 잘 보전되어 있으며 혼효림이 무성하여 봄, 여름, 가을, 겨울이 새롭게 보이는 산이다.'),
(25, '청량산 (서울/경기)', 'EAST', '41610', '광주시', '경기도 광주시 남한산성면 산성리', 497.1, 37.480163, 127.176128, 63, 125, '광주시 남한산성면에 있는 해발 497.1m의 산이다. 남한산성의 주봉으로 정상에 수어장대가 있다.'),
(26, '태화산 (경기)', 'EAST', '41610', '광주시', '경기도 광주시 도척면 유정리', 641.1, 37.292152, 127.293686, 65, 121, '경기도 광주시 남쪽 끝에 자리한 도척면은 백제 온조왕이 한강유역에 도읍을 정하려고 이곳을 탐사할 때 자로 재고 또 쟀다고 해서 도척(都尺)이란 이름이 붙었다고 한다. 이러한 도척면 북서쪽을 병풍처럼 에워싸고 있는 산이 바로 태화산이다.'),
(27, '해협산', 'EAST', '41610', '광주시', '경기도 광주시 남종면 수청리', 527.7, 37.491563, 127.356282, 66, 125, '경기도 광주군 퇴촌면과 남종면의 경계에 솟은 해협산은 북으로 정암산(403m)과 한강을 끼고, 남쪽의 관산(555m), 양자산(704m)과 함께 나지막한 산이다. 비록 산은 작으나 산세가 험하지 않고 강과 연접해 있어 가족단위 산행과 물놀이를 즐기기 적당한 곳이다.'),
(28, '문수산 (김포)', 'NORTH', '41570', '김포시', '경기도 김포시 월곶면 성동리', 376.0, 37.7390901, 126.5486096, 52, 130, '김포가도를 달려 월곶면에 이르면 김포평야의 자그마한 야산들 사이로 문수산이 우뚝 서 있고 강화도를 갈 때 쉽게 지나치는 산이다. 강화도를 가다가 보면 강화대교를 건너기 직전 우측으로 얼핏 보기에도 대단해 보이는 산성을 볼 수 있는데 이것이 바로 문수산성이다.'),
(29, '승마산', 'NORTH', '41570', '김포시', '경기도 김포시 대곶면 약암리', 130.0, 37.631025, 126.560698, 53, 128, '김포시 대곶면 약암리에 있는 해발 130m의 산이다.'),
(30, '애기봉', 'NORTH', '41570', '김포시', '경기도 김포시 하성면 가금리', 156.0, 37.7550759, 126.5958029, 53, 131, '김포시 하성면 가금리에 있는 해발 156m의 산이다. 한강 하구 건너 북한 땅이 보이는 전망대가 있다.'),
(31, '고래산', 'EAST', '41360', '남양주시', '경기도 남양주시 조안면 시우리', 528.5, 37.606909, 127.29669, 65, 128, '남양주시 조안면 시우리에 있는 해발 528.5m의 산이다.'),
(32, '금대산', 'EAST', '41360', '남양주시', '경기도 남양주시 와부읍 덕소리', 89.1, 37.58369, 127.218671, 64, 127, '남양주시 와부읍 덕소리에 있는 해발 89.1m의 산이다.'),
(33, '백봉산', 'EAST', '41360', '남양주시', '경기도 남양주시 평내동', 590.0, 37.6389172, 127.2581618, 65, 128, '남양주시 평내동에 있는 해발 590m의 산이다. 천마산에서 남쪽으로 이어지는 능선에 있다.'),
(34, '예봉산', 'EAST', '41360', '남양주시', '경기도 남양주시 와부읍 팔당리', 678.8, 37.559152, 127.261132, 65, 127, '경기도 남양주시 와부읍과 조안면 경계를 이루는 예봉산(683.2m)은 한북정맥에서 가지를 친 능선 끝머리에 해당하는 산이다. 이 산줄기는 다시 남동쪽으로 이어져 율리봉, 예빈산을 들어 올린 다음 북한강과 남한강이 합수되는 두물머리와 한강에서 모두 사그라진다.'),
(35, '예빈산', 'EAST', '41360', '남양주시', '경기도 남양주시 와부읍 팔당리', 590.0, 37.5465274, 127.271354, 65, 126, '남양주시 와부읍 팔당리에 있는 해발 590m의 산이다. 예봉산 동쪽에 이웃해 있으며 팔당호를 내려다본다.'),
(36, '운길산', 'EAST', '41360', '남양주시', '경기도 남양주시 조안면 진중리', 606.5, 37.572604, 127.294586, 65, 127, '운길산은 서울에서 동쪽으로 40㎞, 북한강과 남한강이 합류되는 양수리에서 서북쪽으로 4㎞ 거리에 솟아 있는 산이다. 산 아래까지 시내버스가 연결되고 있어 교통이 편리하고, 산세가 부드럽고 등산로가 순탄하여 가족산행이나 가벼운 주말산행에 적합한 곳이다.'),
(37, '적갑산', 'EAST', '41360', '남양주시', '경기도 남양주시 와부읍 도곡리', 566.3, 37.572419, 127.256668, 65, 127, '남양주시 와부읍에 있는 해발 566.3m의 산이다. 예봉산과 능선으로 이어져 예봉산·운길산과 함께 오르는 경우가 많다.'),
(38, '천마산 (남양주)', 'EAST', '41360', '남양주시', '경기도 남양주시 오남읍 팔현리', 810.3, 37.680211, 127.273346, 65, 129, '마석에서 서북쪽으로 4.5km 떨어져 있는 산으로 1983년 군립공원으로 지정되어 휴일이면 많은 사람이 몰리고 있다. 특히 이곳은 스키장과 청소년 심신 수련장 등이 있으며, 산의 형세가 험하지 않고 나무가 울창하여 당일 등산코스로 알맞다.'),
(39, '소요산', 'NORTH', '41250', '동두천시', '경기도 동두천시 상봉암동', 587.5, 37.938549, 127.088009, 62, 135, '서울에서 44km, 동두천시청에서 동북쪽으로 약 5km의 거리에 있는 소요산은 경치가 뛰어나 경기도의 ''소금강''이라 불린다.'),
(40, '해룡산 (동두천/포천)', 'NORTH', '41250', '동두천시', '경기도 동두천시 탑동동', 661.2, 37.873962, 127.128332, 62, 133, '해룡산은 동두천 탑동 일원에 있는 높이 661m의 산입니다. 해룡산은 회암령인 천보산을 따라 산계를 형성하고 동북으로 뻗어 탑동 왕방마을 오지재에서 끝나며 왕방산과 접한다.'),
(41, '성주산', 'CENTRAL', '41190', '부천시', '경기도 부천시 소사본동', 216.5, 37.471795, 126.778298, 56, 125, '부천시 소사본동에 있는 해발 216.5m의 산이다. 부천의 주산으로 시흥시와 경계를 이룬다.'),
(42, '원미산', 'CENTRAL', '41190', '부천시', '경기도 부천시 원미동', 168.0, 37.49517, 126.79995, 57, 125, '부천의 주산인 성주산과 함께 많은 시민이 찾고 있는 원미산은 멀뫼로 와 수주로 사이에 있다. 접근성이 좋은 원미산은 해발 168m, 면적 214ha의 산으로 시민들의 산책코스로 많이 이용되고 있다.'),
(43, '관악산', 'CENTRAL', '41290', '과천시', '서울특별시 관악구 신림동 / 경기도 과천시 중앙동', 632.2, 37.44514, 126.964238, 60, 124, '관악산은 서울시 관악구와 금천구, 경기도 과천시와 안양시에 걸쳐 있어 북한산, 도봉산과 더불어 누구나 쉽게 찾는 친근한 산이다. 멀리서 보면 온통 바위로 뒤덮여 있는 산세를 가진 관악산은 해발은 낮으나 등산로 곳곳에 위험한 바위가 있어 조심해야 한다.'),
(44, '아차산', 'EAST', '41310', '구리시', '서울특별시 광진구 중곡동', 287.0, 37.566844, 127.102742, 62, 127, '너른 벌판 위를 달리던 한 줄기 바람이 갑작스럽게 숨을 몰아쉬어야 하는 곳, 우뚝 아차(蛾嵯)라고 이름 한 곳이 바로 아차산이다. 정상표고 200m 되는 지점에서 시작하여 동남의 한강 변 쪽으로 경사진 산허리의 윗부분을 둘러싸고 있는 산성의 형태가 남아 있다.'),
(45, '불암산', 'EAST', '41360', '남양주시', '서울특별시 노원구 상계동', 509.7, 37.663701, 127.095301, 62, 129, '불암산은 남양주시 별내면 화접리와 서울특별시 노원구와 경계를 이룬다. 산 서쪽에는 서울특별시가 있고 동쪽으로는 남양주시 별내면이 있으며 바위산이라 수목은 울창하지 않지만, 능선이 기암으로 이어지고 봄철 철쭉꽃이 장관을 이룬다.'),
(46, '수락산', 'EAST', '41360', '남양주시', '서울특별시 노원구 상계동 / 경기도 남양주시 별내면 청학리', 640.6, 37.699252, 127.081386, 62, 130, '도봉산과 마주 보고 있는 수락산은 상계동에 대단위 아파트촌이 건립되면서 상계아파트 단지의 뒷산이 되었다. 도봉산보다 규모는 작지만 산 곳곳에 노출된 암벽으로 인해 경관이 뛰어나고 동쪽에는 신라 때 창건된 내원암과 흥국사가 있다.'),
(47, '북한산', 'NORTH', '41280', '고양시', '서울특별시 서대문구 홍은동', 835.6, 37.6586301, 126.9780032, 60, 129, '북한산이 걸쳐있는 행정구역은 서울, 경기도의 많은 지자체에 걸쳐있는 큰 산이다.'),
(48, '구릉산', 'EAST', '41310', '구리시', '서울특별시 중랑구 신내동', 177.9, 37.6078472, 127.1036667, 62, 128, '서울 중랑구 신내동에 있는 해발 177.9m의 산이다. 서울 중랑구와 구리시 경계에 있다.'),
(49, '망우산', 'EAST', '41310', '구리시', '서울특별시 중랑구 망우동', 281.7, 37.5933398, 127.1132963, 62, 127, '망우산(망우리 공원)은 중랑구의 동남 측과 구리시와 경계에 걸쳐있으며, 행정구역상 서울시 중랑구 망우동, 면목동, 경기도 구리시에 남북으로 길게 있다.'),
(50, '용마산 (경기)', 'EAST', '41310', '구리시', '서울특별시 중랑구 면목동', 348.6, 37.571498, 127.095153, 62, 127, '용마산은 아차산과 망우산의 가운데 위치하며 동쪽에 흐르는 한강과 그 주변의 자연경관을 비롯해 남양주 일원, 구리시, 서울 시내, 데모산, 관악산, 불암산, 수락산, 도봉산 북한산까지 조망할 수 있어 전망대라는 느낌이 강하게 들 정도다.'),
(51, '영장산', 'EAST', '41130', '성남시', '경기도 성남시 수정구 복정동', 193.7, 37.453669, 127.138342, 63, 124, '영장산은 청량산의 자락이 탄천을 향해 일직선으로 내려오다 마지막 안간힘을 쓰듯 도드라진 산이다. 높이는 193m이며, 이 산 북쪽은 복정동이고 남쪽은 태평동이다.'),
(52, '인릉산', 'EAST', '41130', '성남시', '경기도 성남시 수정구 심곡동', 327.0, 37.4449951, 127.0880012, 62, 124, '성남시 수정구 심곡동에 있는 해발 327m의 산이다. 서울 서초구와 성남시 경계에 있으며 산 이름은 기슭의 조선 순조 능인 인릉에서 왔다.'),
(53, '광교산', 'CENTRAL', '41110', '수원시', '경기도 수원시 장안구 상광교동', 581.2, 37.33144, 127.036028, 61, 122, '광교산은 원래 광악산이었는데 928년 왕건이 후백제 견훤을 평정하고 나서 산 근처에 행궁을 차리고 군사를 위로할 때 산 정상에서 불빛이 하늘로 솟아오르는 것을 보고 이 산은 ''부처님의 가르침을 주는 산'' 이라 하여 이름을 광교산으로 붙였다고 전해진다.'),
(54, '여기산', 'CENTRAL', '41110', '수원시', '경기도 수원시 권선구 서둔동', 104.1, 37.280447, 126.983639, 60, 121, '수원시 권선구 서둔동에 있는 해발 104.1m의 산이다.'),
(55, '칠보산 (경기)', 'CENTRAL', '41110', '수원시', '경기도 수원시 권선구 호매실동 / 경기도 화성시 매송면 원평리', 238.5, 37.260053, 126.932678, 59, 120, '수원시 권선구 호매실동에 있는 해발 238.5m의 산이다. 수원시와 화성시의 경계에 있다.'),
(56, '팔달산', 'CENTRAL', '41110', '수원시', '경기도 수원시 팔달구 남창동', 145.5, 37.280559, 127.010089, 60, 121, '수원시 팔달구 남창동에 있는 해발 145.5m의 산이다. 수원 화성(華城)이 산줄기를 따라 쌓여 있고 정상에 서장대가 있다.'),
(57, '소래산', 'CENTRAL', '41390', '시흥시', '인천광역시 남동구 장수동', 299.7, 37.452196, 126.7789226, 56, 124, '소래산은 시흥 9경 중의 하나이기도 하다. 산 정상부에서 내려다보면 막힘이 없어 사방이 트여 시야가 넓으며 맑은 날이면 서울을 비롯하여 서해안 바다까지도 한눈에 들어온다.'),
(58, '광덕산 (안산)', 'CENTRAL', '41270', '안산시', '경기도 안산시 단원구 와동', 209.0, 37.339178, 126.837509, 57, 122, '광덕산은 안산시 와동, 고잔동, 월피동, 양상동, 선부동에 걸쳐있는 산으로 해발 209m의 산이다. 조선 때까지만 하더라도 산 모양이 서울을 배반하고 있는 듯하다 하여 쓸모없는 산으로 알려져 왔다.'),
(59, '국사봉 (안성)', 'SOUTH', '41550', '안성시', '경기도 안성시 보개면 남풍리', 444.5, 37.0751195, 127.3400112, 66, 116, '안성시 보개면 남풍리에 있는 해발 444.5m의 산이다.'),
(60, '덕성산', 'SOUTH', '41550', '안성시', '경기도 안성시 죽산면 두교리', 519.0, 36.998129, 127.397227, 67, 114, '안성시 죽산면 두교리에 있는 해발 519m의 산이다.'),
(61, '백운산 (경기)', 'SOUTH', '41550', '안성시', '경기도 안성시 원곡면 반제리', 345.6, 37.027925, 127.152892, 63, 115, '백운산은 평택시 월곡동과 안성시 원곡면을 경계로 길게 이어져 있다. 평택시의 모든 산이 그러하듯이 다른 지역의 산들과 크기를 비교하기가 그렇지만 그래도 평택에서는 조금 큰 산이다.'),
(62, '비봉산 (경기)', 'SOUTH', '41550', '안성시', '경기도 안성시 죽산면 죽산리', 369.8, 37.0893, 127.416, 68, 116, '안성시 죽산면 죽산리에 있는 해발 369.8m의 산이다. 산에 삼국시대 산성인 죽주산성이 있다.'),
(63, '서운산', 'SOUTH', '41550', '안성시', '경기도 안성시 금광면 상중리', 548.0, 36.930519, 127.296625, 66, 113, '경기도 안성시와 충청북도 진천의 경계에 선 서운산은 아담하고 바위가 거의 없는 유순한 산세를 지녔으며 봄이면 계곡과 능선에 진달래와 철쭉이 군락을 이루는 아름다운 산이다.'),
(64, '칠장산', 'SOUTH', '41550', '안성시', '경기도 안성시 죽산면 장계리', 492.1, 37.031179, 127.390027, 67, 115, '경기도 안성군 삼죽면, 죽산면, 금광면에 있는 "칠장산군"(덕성산, 칠현산, 칠장산)은 백두대간 중 속리산에서 가지 쳐 나온 정맥인 금북정맥에 속한 산이다.'),
(65, '칠현산 (경기)', 'SOUTH', '41550', '안성시', '경기도 안성시 죽산면 칠장리', 516.5, 37.01214, 127.395873, 67, 115, '안성시 죽산면 칠장리에 있는 해발 516.5m의 산이다. 기슭에 고찰 칠장사가 있다.'),
(66, '삼성산 (서울/경기)', 'CENTRAL', '41170', '안양시', '경기도 안양시 만안구 석수동', 480.9, 37.435915, 126.939371, 59, 124, '서울시 관악구와 안양시를 경계로 하는 삼성산은 관악산 주능선에서 서쪽으로 뻗어내린 팔봉 능선을 타고 무너미 고개로 내려앉다가 다시 솟구쳐 오른 산으로, 삼성산 아래 국기봉과 삼막사로 많이 알려졌으며, 바위로 된 암산이다.'),
(67, '수리산', 'CENTRAL', '41410', '군포시', '경기도 안양시 만안구 안양동', 469.3, 37.359685, 126.906911, 59, 122, '수리산은 안양, 군포, 안산시 경계에 자리한 산이다. 관악산, 삼성산, 모락산과 이웃하고 있으며 낮으면서도 바위와 숲, 계곡의 경관이 좋아 조선 시대에는 안산의 명산으로 불리기도 했다.'),
(68, '고령산', 'NORTH', '41630', '양주시', '경기도 양주시 백석읍 기산리', 621.1, 37.7575556, 126.9285778, 59, 131, '양주시 백석읍 기산리에 있는 해발 621.1m의 산이다. 양주시와 파주시 경계에 있으며 정상은 앵무봉이고 기슭에 보광사가 있다.'),
(69, '도봉산', 'NORTH', '41630', '양주시', '경기도 양주시 장흥면 울대리', 740.2, 37.6988424, 127.0154594, 60, 130, '양주시 장흥면 울대리에 있는 해발 740.2m의 산이다. 북한산국립공원에 속하며 자운봉을 비롯한 바위 봉우리가 이어진다.'),
(70, '불곡산 (양주)', 'NORTH', '41630', '양주시', '경기도 양주시 산북동', 470.0, 37.799514, 127.026355, 61, 132, '해발 470m로 밋밋하고 특징이 없어 보이지만 작은규모에 비해서는 암릉이 많고 아기자기하고 길게 이어지는 바위산이라 매우 스릴 있으면서도 위험하지 않아서 산행의 묘미를 한껏 즐길 수 있는 산이다.'),
(71, '사패산', 'NORTH', '41630', '양주시', '경기도 양주시 장흥면 울대리', 551.1, 37.722351, 127.010537, 60, 130, '의정부시와 양주시 경계에 있는 해발 551.1m의 산이다. 북한산국립공원에 속하며 정상이 넓은 바위로 되어 있다.'),
(72, '오봉산 (양주)', 'NORTH', '41630', '양주시', '경기도 양주시 장흥면 울대리', 683.7, 37.696769, 127.00131, 60, 130, '양주시 장흥면 울대리에 있는 해발 683.7m의 산이다. 도봉산 서쪽에 있으며 다섯 개의 바위 봉우리가 나란히 솟아 있다.'),
(73, '갈기산 (강원/경기)', 'EAST', '41830', '양평군', '경기도 양평군 청운면 신론리', 685.4, 37.578876, 127.786222, 74, 127, '용두리에서 홍천 방향으로 이어지는 44번 국도 동쪽 옆에 솟아 있는 갈기산은 산 높이는 낮으나 능선 곳곳에 바위가 돌출되어 전망이 좋은 산이다.'),
(74, '금물산', 'EAST', '41830', '양평군', '강원특별자치도 횡성군 서원면 유현리', 775.5, 37.5536425, 127.8503094, 75, 127, '금물산은 경기도 양평군과 강원도 횡성군의 경계를 이루고 있다. 예전에 도둑이 많이 나타나서 붙여진 도둑고개에서 동쪽 횡성 방향으로 내려가면 왼쪽에 나타나는 산이다.'),
(75, '백운봉', 'EAST', '41830', '양평군', '경기도 양평군 옥천면 용천리', 941.2, 37.533478, 127.52714, 69, 126, '양평군 옥천면 용천리에 있는 해발 941.2m의 산이다. 용문산에서 남서쪽으로 뻗은 능선의 뾰족한 봉우리이다.'),
(76, '봉미산', 'EAST', '41830', '양평군', '경기도 양평군 지평면 월산리', 856.0, 37.613659, 127.570371, 70, 128, '용문산(1,157m) 북쪽 능선을 따라 10km 떨어진 곳에 솟은 봉미산은 경기도에서도 오지로 꼽히는 양평군 단월면 산음리에 있다. 산골 마을의 정취가 물씬 풍기는 산음(山陰)리는 용문산의 그늘에 묻혀 음지가 된다고 이름 붙었다.'),
(77, '어비산', 'EAST', '41830', '양평군', '경기도 양평군 옥천면 용천리', 823.0, 37.575287, 127.506498, 69, 127, '경기도 가평군과 양평군의 경계를 이루고 있는 어비산은 유명산 계곡을 사이에 두고 유명산의 동쪽에 솟아 있는 산이다.'),
(78, '용문산 (경기)', 'EAST', '41830', '양평군', '경기도 양평군 옥천면 용천리', 1157.1, 37.561953, 127.548986, 70, 127, '용문산은 경기도에서 네 번째로 높은 산으로 기암괴석과 고산준령을 고루 갖추고 있는 산이다. 본디 미지산이라는 이름으로 불리었는데, 조선을 개국하고 이태조가 등극하면서 ''용문산''이라 바꿔 부르게 되었다고 한다.'),
(79, '유명산', 'EAST', '41830', '양평군', '경기도 양평군 옥쳔면 용천리', 864.0, 37.57537, 127.486766, 69, 127, '국립지리원 발행 지형도에도 마유산으로 표기하다가, 1973년 국토 자오선 종주대가 이 산을 통과하면서 당시 대원 중 홍일점이었던 진유명 씨의 이름을 따서 유명산으로 부르게 되었다.'),
(80, '중미산', 'EAST', '41830', '양평군', '경기도 양평군 서종면 명달리', 834.2, 37.595385, 127.471507, 68, 127, '중미산은 경기도 가평군 설악면과 양평군 서종면의 경계에 있는 산이다. 유명산, 소구니산과 더불어 서너치 고개를 사이에 두고 솟아있는 중미산은 그동안 유명산에 가려 빛을 보지 못했으나 중미산 자연 휴양림이 조성되면서부터 주목받고 있다.'),
(81, '중원산', 'EAST', '41830', '양평군', '경기도 양평군 용문면 신점리', 800.0, 37.5586466, 127.601842, 71, 127, '용문산, 백운봉, 도일봉과 더불어 웅장한 절경을 이루어 경기의 금강산이라 불리기도 하는 중원산은 경기 양평 용문면과 단월면의 경계에 있는 산이다.'),
(82, '추읍산', 'EAST', '41830', '양평군', '경기도 양평군 용문면 삼성리', 582.6, 37.4554825, 127.5735999, 70, 124, '추읍산은 양평과 용문 중간에 있는 산으로 추읍산, 혹은 칠읍산이라 불렀다 한다. 이는 주변의 일곱 개 읍, 즉 양평, 용문, 개군, 지제, 강상, 옥천, 청운 등이 한눈에 보인 데서 유래한 것이다.'),
(83, '편전산', 'EAST', '41830', '양평군', '경기도 양평군 옥천면 용천리', 378.0, 37.541007, 127.480285, 68, 126, '등산을 즐기는 사람이라도 경기도 양평에 편전산이 있다는 것을 아는 사람은 그다지 많지 않다. 널리 알려지지 않은 산들이 그렇듯이 편전산은 호젓한 산행을 즐기기 좋으며 수풀이 우거져 덥수룩한 산길을 걷는 묘미가 있는 산행지이다.'),
(84, '대렴봉', 'SOUTH', '41670', '여주시', '경기도 여주시 금사면 상호리', 418.8, 37.397884, 127.470924, 68, 123, '여주시 금사면 상호리에 있는 해발 418.8m의 산이다.'),
(85, '북성산', 'SOUTH', '41670', '여주시', '경기도 여주시 능서면 신지리', 257.6, 37.28499, 127.595202, 71, 121, '북성산은 거리가 그리 길지 않고 경사도 완만하여 가족과 함께 산책하기에 좋은 산으로 많은 사람이 찾고 있다. 농로의 끝에서 시작되는 작은 소로길을 따라 1㎞ 올라가다 보면 마치 쉬어가라고 만들어 놓은 듯 약수터와 벤치가 놓여 있다.'),
(86, '오갑산', 'SOUTH', '41670', '여주시', '경기도 여주시 점동면 관한리', 609.4, 37.139162, 127.696922, 72, 118, '오갑산은 2개도(경기, 충북), 3개 군(음성, 여주, 충주)이 경계를 이루고 있는 명산으로 삼국시대에는 오압산(梧壓山)이라 불리었다. 한때 오압사라는 거찰을 배치하고 있었으나 지금은 그 흔적을 찾아볼 수 없으며 미륵좌불 하나만이 지방 사적으로 지정되어 보호되고 있다.'),
(87, '황학산', 'SOUTH', '41670', '여주시', '경기도 여주시 능현동', 175.1, 37.271436, 127.647503, 71, 120, '여주시 능현동에 있는 해발 175.1m의 산이다. 산자락에 황학산수목원이 있다.'),
(88, '고대산 (경기/강원)', 'NORTH', '41800', '연천군', '경기도 연천군 신서면 대광리', 832.0, 38.198651, 127.166317, 63, 140, '경원선 철도가 휴전선에 막혀 이제는 달리지 못하고 멈추는 곳에 고대산이 솟아 있다. 고대산은 등산객들이 자유롭게 산행을 할 수 있는 산 중에서 휴전선에 가장 가깝게 있는 산이다.'),
(89, '고왕산', 'NORTH', '41800', '연천군', '경기도 연천군 왕징면 고왕리', 355.0, 38.10569, 126.91455, 59, 138, '연천군 왕징면 고왕리에 있는 해발 355m의 산이다.'),
(90, '종자산 (경기)', 'NORTH', '41800', '연천군', '경기도 연천군 연천읍 부곡리', 643.8, 38.077917, 127.190853, 63, 138, '추가령곡에서 발원한 한탄강이 철원평야를 지난 뒤 임진강과 합류하기 전에 만나는 것이 종자산이다. 우리말로 씨앗산이라 하는 종자산은 주위의 보장산이나 불무산, 은장산과는 다른 모습의 암산으로 보는 이를 압도한다.'),
(91, '여계산', 'CENTRAL', '41370', '오산시', '경기도 오산시 금암동', 158.6, 37.174053, 127.039108, 61, 118, '궐리사부터 물향기 수목원을 거쳐 지곳동과 가장동까지 노선이 이어진다. 고도가 낮으며 지세도 험하지 않다.'),
(92, '달봉산', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 남사면 완장리', 206.9, 37.164751, 127.191839, 64, 118, '용인시 처인구 남사면에 있는 해발 206.9m의 산이다.'),
(93, '매미산', 'SOUTH', '41460', '용인시', '경기도 용인시 기흥구 하갈동', 157.2, 37.235836, 127.089972, 62, 120, '용인시 기흥구 하갈동에 있는 해발 157.2m의 산이다.'),
(94, '문수산 (용인)', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 동림리', 221.0, 37.336733, 127.185164, 63, 122, '높이가 403.2m이며 용인시 원삼면 북서쪽에 있는 산으로 능선은 비탈면이 완만하여 초보자도 비교적 완만하게 등산을 할 수가 있으며 산행 도중 정상에서 바라보는 경치는 한 폭의 그림 같으며 그리고 도중에 마주치는 유형문화재 마애보살상과 호국사찰로 유명한 와우정사와 법륜사도 볼만한 구경거리다.'),
(95, '법화산 (경기)', 'SOUTH', '41460', '용인시', '경기도 용인시 기흥구 마북동', 383.2, 37.305536, 127.148445, 63, 121, '법화산 등정은 등산로가 좁고 가파르며 낮에는 등산객이 많고 야간에는 길이 좁아 등산하기에 불편하다. 정상에 올라 능성길로 접어들면 소나무가 빽빽해 길이 푹신하여 걷기 편하고 느낌이 좋다.'),
(96, '부아산 (경기)', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 역삼동', 402.9, 37.227251, 127.159986, 63, 119, '용인시 처인구 역삼동에 있는 해발 402.9m의 산이다.'),
(97, '석성산 (경기)', 'SOUTH', '41460', '용인시', '경기도 용인시 기흥구 중동', 471.3, 37.272593, 127.172944, 63, 120, '용인시 기흥구 중동에 있는 해발 471.3m의 산이다.'),
(98, '아람산 (용인)', 'SOUTH', '41460', '용인시', '경기도 용인시 기흥구 하갈동', 147.1, 37.2471574, 127.0856972, 62, 120, '용인시 기흥구 하갈동에 있는 해발 147.1m의 산이다.'),
(99, '청명산 (수원/용인)', 'SOUTH', '41460', '용인시', '경기도 용인시 기흥구 하갈동', 190.1, 37.258418, 127.083705, 62, 120, '경기도 수원시 영통구 영통동과 용인시 기흥읍의 경계에 있는 산으로 정상에 서면 탁 트여 사방이 훤히 내려다보인다. 그리고 정상은 용인시에 있고 또한 관리도 용인시에서 한다.'),
(100, '함박산 (경기)', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 남동', 349.3, 37.213893, 127.188899, 64, 119, '용인시 처인구 남동에 있는 해발 349.3m의 산이다.'),
(101, '향수산', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 포곡읍 신원리', 457.0, 37.311314, 127.18573, 63, 121, '용인시 처인구 포곡읍에 있는 해발 457m의 산이다.'),
(102, '형제봉 (용인)', 'SOUTH', '41460', '용인시', '경기도 용인시 처인구 운학동', 453.6, 37.208133, 127.270158, 65, 119, '용인시 처인구 운학동에 있는 해발 453.6m의 산이다.'),
(103, '모락산', 'CENTRAL', '41430', '의왕시', '경기도 의왕시 내손동', 385.8, 37.370509, 126.978647, 60, 122, '의왕시 내손동에 있는 해발 385.8m의 산이다. 의왕시와 안양시 경계에 있으며 모락산성 터가 남아 있다.'),
(104, '바라산', 'CENTRAL', '41430', '의왕시', '경기도 의왕시 학의동', 427.5, 37.36872, 127.0271, 61, 122, '바라산은 백운산, 광교산과 능선으로 연결되는 이웃한 산으로 이들 산은 경부고속도로와 서울특별시, 수원 간의 옛 도로 사이에 약 10여km에 걸쳐 수원까지 뻗어 있다.'),
(105, '백운산 (의왕시)', 'CENTRAL', '41430', '의왕시', '경기도 의왕시 왕곡동', 566.0, 37.353555, 127.017006, 61, 122, '백운산(시흥)은 바라산, 광교산과 능선으로 연결되는 이웃한 산으로 능선은 매우 한적한 편이다. 경기도 의왕시의 백운저수지의 뒷산인 해발 567m의 산으로 서울특별시에서 가까워 찾기 쉬운 산이다.'),
(106, '오봉산 (의왕)', 'CENTRAL', '41430', '의왕시', '경기도 의왕시 이동', 209.8, 37.344424, 126.962203, 60, 122, '높이 205M의 그리 높지 않은 오봉산은 의왕시청 바로 뒤편에 있어 접근이 쉽다. 높지 않은 산이지만 암벽등반을 위한 높이 18M, 폭 30M의 병풍바위를 찾는 전문산악인들과 관광객들이 끊이지 않는 곳이다.'),
(107, '천보산', 'NORTH', '41150', '의정부시', '경기도 의정부시 금오동', 335.5, 37.763958, 127.0660928, 61, 131, '의정부과 동두천 중간쯤에 양주시 덕정리 철로 변 마을에서 동쪽으로 나 있는 길을 따라가다 보면 남북으로 뻗은 산줄기가 보인다. 양주와 포천 땅을 가르는 산줄기인데 이 산줄기의 중앙부에 우뚝 솟은 산이 천보산이다.'),
(108, '도드람산', 'SOUTH', '41500', '이천시', '경기도 이천시 마장면 장암리', 347.0, 37.2679417, 127.3921944, 67, 120, '‘이천의 소금강’으로 불리는 도드람산은 남북으로 이어진 작고 낮은 산줄기에 불뚝불뚝 솟아오른 바위봉우리의 아기자기한 모양새가 가시가 돋아 난 공룡 등과도 같다.'),
(109, '설봉산 (경기)', 'SOUTH', '41500', '이천시', '경기도 이천시 관고동', 393.1, 37.281004, 127.413214, 67, 121, '설봉산은 이천시가지를 서쪽에서 북동방향과 남동방향으로 둘러싸고 있는 이천의 진산으로 북악산(北嶽山)이라 부르기도 하였고, 마치 학이 날개를 편 형상을 닮았다 하여 무학산(舞鶴山), 부학산(浮鶴山)이라고도 하였다.'),
(110, '설성산', 'SOUTH', '41500', '이천시', '경기도 이천시 장호원읍 선읍리', 290.7, 37.143045, 127.556185, 70, 118, '이천시 장호원읍 선읍리에 있는 해발 290.7m의 산이다. 산에 설성산성이 있다.'),
(111, '감악산 (경기)', 'NORTH', '41480', '파주시', '경기도 파주시 적성면 객현리', 674.9, 37.941148, 126.970076, 60, 135, '예로부터 경기 오악 중 하나로 꼽힌 산으로, 삼국시대부터 6·25전쟁 때까지 전략 요충지였다. 산자락 설마천 계곡에 영국군 전적비가 있다.'),
(113, '덕지산', 'SOUTH', '41220', '평택시', '경기도 평택시 청북읍 어소리', 137.5, 37.06167, 126.934594, 59, 116, '덕지산은 화성시 요당마을과 경계를 이루며 청북면 고렴리와 어소리로 길게 이어지며 해발(GPS) 146.2M이다. 정상부로 오르는 등산로는 가파르나 정상에서 바라보는 서해대교와 평택항을 바라다보면 흐르는 땀방울이 씻기어진다.'),
(114, '부락산', 'SOUTH', '41220', '평택시', '경기도 평택시 지산동', 149.4, 37.06912, 127.078858, 62, 116, '평택시 지산동에 있는 해발 149.4m의 산이다.'),
(115, '팔룡산', 'SOUTH', '41220', '평택시', '경기도 평택시 도일동', 138.0, 37.04776, 127.12046, 62, 115, '평택시 도일동과 안성시 원곡면에 있는 팔룡산은 덕암산과 안성의 고성산 사이에 널리 알려진 산은 아니지만 완만하고 부드러운 능선과 아직은 탐방객들이 적어 훼손되지 않은 자연 그대로의 산행을 즐길 수 있는 산이다.'),
(116, '관음산', 'NORTH', '41650', '포천시', '경기도 포천시 영북면 산정리', 732.1, 38.029059, 127.310379, 65, 137, '관음산은 북동쪽으로 명성산과 주 능선이 이어져 있다. 정상에서 북쪽 산자락에는 관광명소인 산정호수가 자리 잡고 있으며, 남쪽으로는 드라이브코스인 영평천이 흐르고 있어 볼거리가 많은 곳이다.'),
(117, '광덕산 (강원/경기)', 'NORTH', '41650', '포천시', '경기도 포천시 이동면 도평리', 1049.2, 38.11546, 127.430963, 67, 139, '한북정맥에 들머리가 되는 광덕산은 경기도에서는 가장 북쪽에 있는 산이며, 강원도 화천군과 철원군의 경계를 이루고 있으며, 거의 정상 부위까지 군사 비상도로가 개설되어 있고 산자락 곳곳에 군사시설이 있어 지형적으로 군사 요충지임을 말해주는 산이다.'),
(118, '명성산', 'NORTH', '41650', '포천시', '강원특별자치도 철원군 갈말읍 신철원리', 922.0, 38.1042997, 127.3381489, 66, 138, '명성산은 서울에서 동북으로 84Km, 운천에서 약 4Km 거리에 있다. 산자락에 산정호수를 끼고 있어 등산과 호수의 정취를 만끽할 수 있는 산이다.'),
(119, '박달봉', 'NORTH', '41650', '포천시', '경기도 포천시 이동면 도평리', 820.0, 38.096855, 127.412336, 67, 138, '포천시 이동면 도평리에 있는 해발 820m의 산이다.'),
(120, '백운산 (경기/강원)', 'NORTH', '41650', '포천시', '경기도 포천시 이동면 도평리', 903.0, 38.080452, 127.447032, 68, 138, '경기도 포천군 이동면과 강원도 화천군 사내면의 경계를 이루는 백운산은 부드러운 산세와 광덕고개에서 산행이 시작되므로 가볍게 산행을 즐기려는 사람들이 많이 찾는다. 주말을 이용해 가족과 함께 등반하기에도 적격인 곳이다.'),
(121, '왕방산', 'NORTH', '41650', '포천시', '경기도 포천시 신북면 심곡리', 736.8, 37.895754, 127.15576, 63, 134, '포천읍 바로 뒤에 솟은 왕방산은 덩치가 크고 품이 넉넉해 보이는 인자한 시골 아낙네 같은 산이다. 또한, 포천읍의 진산으로 남북으로 길게 누운, 바위가 그리 많지 않은 육산이다.'),
(122, '운악산', 'NORTH', '41650', '포천시', '경기도 포천시 화현면 화현리 / 경기도 가평군 조종면 운악리', 934.7, 37.87685, 127.325, 66, 134, '운악산은 경기도의 동북 산간 지역에 위치한다. 북쪽에는 한북정맥이 북동에서 남서 방향으로 뻗어있고 남쪽에는 북한강이 동서로 흐르고 있다.'),
(123, '종현산', 'NORTH', '41650', '포천시', '경기도 포천시 신북면 덕둔리', 584.7, 37.980368, 127.123236, 62, 136, '종현산은 신북면 덕둔리 북쪽에 우뚝 솟아 있으며 경기 포천 산악지역의 상징적 존재이기도 하다. 그러나 경기도의 소금강이라 불리는 소요산(532m) 북쪽에 인접한 산으로 유명한 산과 이웃해 있고 교통이 불편하다는 이유로 사람들 사이에 많이 알려지지 않은 산이다.'),
(124, '주금산', 'NORTH', '41650', '포천시', '경기도 포천시 내촌면 소학리', 813.6, 37.7843935, 127.2680294, 65, 132, '산이 부드럽고 아름다워 일명 비단산이라고도 불리는 주금산은 운악산과 천마산의 중간지점에 가장 높이 솟아있는 산이다. 남쪽의 아름다운 비금계곡은 도심 근교의 대표적 피서지 중 하나다.'),
(125, '객산', 'EAST', '41450', '하남시', '경기도 하남시 교산동', 292.1, 37.513479, 127.211593, 64, 126, '하남시 교산동에 있는 해발 292.1m의 산이다.'),
(126, '검단산 (하남/광주)', 'EAST', '41450', '하남시', '경기도 하남시 하산곡동', 658.4, 37.517615, 127.249417, 64, 126, '하남시청에서 동쪽으로 5km 떨어져 있는 산으로 일설에 의하면 검단선사가 은거하였다 하여 검단산으로 불린다. 산행 초입은 야산과 같아 느낌을 주지만 산 중간쯤 오르면 어느 산 못지않게 뛰어난 숲과 아름다운 풍경과 고사목이 군데군데 널려 있다.'),
(127, '금암산', 'EAST', '41450', '하남시', '경기도 하남시 항동', 321.2, 37.506711, 127.179949, 63, 125, '하남시 항동에 있는 해발 321.2m의 산이다.'),
(128, '남한산', 'EAST', '41450', '하남시', '경기도 하남시 상산곡동', 522.1, 37.480594, 127.2040808, 64, 125, '하남시 상산곡동에 있는 해발 522.1m의 산이다. 남한산성이 산 능선을 따라 둘러쳐져 있으며 남한산성은 유네스코 세계유산이다.'),
(129, '이성산', 'EAST', '41450', '하남시', '경기도 하남시 춘궁동', 208.0, 37.5267035, 127.1822421, 63, 126, '하남시 춘궁동에 있는 해발 208m의 산이다. 산 위에 삼국시대 산성인 이성산성이 있다.'),
(130, '일자산', 'EAST', '41450', '하남시', '서울특별시 강동구 둔촌동', 74.2, 37.529261, 127.1510115, 63, 126, '서울 강동구 둔촌동에 있는 해발 74.2m의 산이다. 서울 강동구와 하남시 경계에 한일(一) 자처럼 길게 뻗은 낮은 능선이다.'),
(131, '천마산 (하남)', 'EAST', '41450', '하남시', '서울특별시 송파구 마천동', 141.4, 37.5034322, 127.1575021, 63, 125, '서울 송파구 마천동에 있는 해발 141.4m의 산이다. 서울 송파구와 하남시 경계에 있다.'),
(132, '건달산', 'CENTRAL', '41590', '화성시', '경기도 화성시 봉담읍 세곡리', 335.5, 37.190927, 126.92112, 59, 119, '화성시 봉담읍 세곡리에 있는 해발 335.5m의 산이다.'),
(133, '무봉산', 'CENTRAL', '41590', '화성시', '경기도 평택시 진위면 동천리', 208.8, 37.115989, 127.099369, 62, 117, '무봉산은 옛 진위 현의 주산이다. 주변에서 가장 높은 산이어서 정상부에 오르면 서남쪽으로는 삼남대로가 지났던 1번 국도가 내려다보인다.'),
(134, '방울산', 'CENTRAL', '41590', '화성시', '경기도 화성시 만세구 향남읍', 138.0, 37.12184, 126.93485, 59, 117, '화성시 만세구 향남읍에 있는 해발 138m의 산이다.'),
(135, '서봉산', 'CENTRAL', '41590', '화성시', '경기도 화성시 정남면 백리', 250.4, 37.158749, 126.944844, 59, 118, '화성시 정남면 백리에 있는 해발 250.4m의 산이다.'),
(136, '서학산', 'CENTRAL', '41590', '화성시', '경기도 화성시 향남읍 장짐리', 142.7, 37.146556, 126.904143, 59, 118, '산기슭이 완만하고 험한 악산이 아니다.'),
(137, '심술산', 'CENTRAL', '41590', '화성시', '경기도 화성시 만세구 팔탄면', 104.4, 37.109693, 126.8780591, 58, 117, '화성시 만세구 팔탄면에 있는 해발 104.4m의 산이다.'),
(138, '쌍봉산', 'CENTRAL', '41590', '화성시', '경기도 화성시 우정읍 조암리', 117.7, 37.092478, 126.818997, 57, 116, '화성시 우정읍 조암리에 있는 해발 117.7m의 산이다.'),
(139, '오두산 (화성)', 'CENTRAL', '41590', '화성시', '경기도 화성시 팔탄면 덕천리', 140.6, 37.144386, 126.884722, 58, 118, '화성시 팔탄면 덕천리에 있는 해발 140.6m의 산이다.'),
(140, '지내산', 'CENTRAL', '41590', '화성시', '경기도 화성시 효행구 봉담읍', 270.0, 37.2228724, 126.9143441, 59, 119, '화성시 효행구 봉담읍에 있는 해발 270m의 산이다.'),
(141, '태봉산 (화성시)', 'CENTRAL', '41590', '화성시', '경기도 화성시 정남면 보통리', 223.8, 37.189311, 126.952814, 59, 119, '화성시 정남면 보통리에 있는 해발 223.8m의 산이다.')
)
SELECT coalesce(expected.id, actual.id) AS id,
       CASE WHEN actual.id IS NULL THEN 'missing_in_db' WHEN expected.id IS NULL THEN 'extra_in_db' ELSE 'different_values' END AS issue
FROM expected FULL OUTER JOIN mountains actual ON actual.id = expected.id
WHERE ROW(actual.id, actual.name, actual.region, actual.sigungu_code, actual.sigungu_name, actual.address, actual.height, actual.lat, actual.lng, actual.grid_nx, actual.grid_ny, actual.description) IS DISTINCT FROM ROW(expected.id, expected.name, expected.region, expected.sigungu_code, expected.sigungu_name, expected.address, expected.height, expected.lat, expected.lng, expected.grid_nx, expected.grid_ny, expected.description)
ORDER BY id;

