SELECT coalesce(expected.id, actual.id) AS id,
       CASE WHEN actual.id IS NULL THEN 'missing_in_db' WHEN expected.id IS NULL THEN 'extra_in_db' ELSE 'different_values' END AS issue
FROM expected FULL OUTER JOIN courses actual ON actual.id = expected.id
WHERE ROW(actual.id, actual.mountain_id, actual.source, actual.name, actual.start_name, actual.start_lat, actual.start_lng, actual.start_elevation, actual.climb, actual.length_km, actual.up_min, actual.down_min, actual.difficulty, actual.risk, md5(actual.path)) IS DISTINCT FROM ROW(expected.id, expected.mountain_id, expected.source, expected.name, expected.start_name, expected.start_lat, expected.start_lng, expected.start_elevation, expected.climb, expected.length_km, expected.up_min, expected.down_min, expected.difficulty, expected.risk, expected.path_md5)
ORDER BY id;

SELECT count(*) AS dangling_activity_mountains FROM hiking_activities a LEFT JOIN mountains m ON m.id=a.mountain_id WHERE m.id IS NULL;
SELECT count(*) AS dangling_or_cross_mountain_activity_courses FROM hiking_activities a LEFT JOIN courses c ON c.id=a.course_id WHERE a.course_id IS NOT NULL AND (c.id IS NULL OR c.mountain_id<>a.mountain_id);
SELECT count(*) AS dangling_journal_activities FROM hiking_records j LEFT JOIN hiking_activities a ON a.id=j.hiking_activity_id WHERE j.hiking_activity_id IS NOT NULL AND a.id IS NULL;
ROLLBACK;
